import assert from "node:assert/strict";
import * as fs from "node:fs";

const read = (file) => fs.readFileSync(file, "utf8");
const pkg = JSON.parse(read("package.json"));
const tools = JSON.parse(read(".github/release-tools/package.json"));
const toolsLock = JSON.parse(read(".github/release-tools/package-lock.json"));
const renovate = JSON.parse(read(".github/renovate.json"));
assert.deepEqual(Object.keys(tools.dependencies).sort(), ["conventional-commits-parser", "semver"]);
assert.deepEqual(toolsLock.packages[""].dependencies, tools.dependencies, "locked coordinator dependencies differ from package manifest");
assert.equal(tools.engines.node, ">=22.19.0");
assert.equal(pkg.name, "@soulwaxx/pi-skill-autocomplete");
assert.match(pkg.version, /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)$/);
assert.ok(pkg.files.includes("README.md") && pkg.files.includes("LICENSE"));
for (const [name, command] of Object.entries({ "release:check": "node .github/release-tools/check.mjs", "test:release": "node tests/run-release-tests.mjs" })) assert.equal(pkg.scripts[name], command, `${name} script path changed unexpectedly`);
for (const file of fs.readdirSync(".github/workflows").filter((name) => name.endsWith(".yml"))) {
  const text = read(`.github/workflows/${file}`);
  for (const match of text.matchAll(/^[ \t]+(?:-[ \t]+)?uses:[ \t]+([^\s]+)/gm)) assert.match(match[1], /@[0-9a-f]{40}$/, `${file} must pin action digests`);
  assert.match(text, /^permissions:\n\s+contents: read\s*$/m, `${file} must default to read-only permissions`);
}
const ci = read(".github/workflows/test.yml");
const release = read(".github/workflows/release.yml");
const verifyJob = release.split("\n  publish:")[0];
const publishJob = release.split("\n  publish:")[1] ?? "";
const prTitle = read(".github/workflows/pr-title.yml");
const renovateWorkflow = read(".github/workflows/renovate.yml");
const pinnedVersion = (text, name, datasource, depName) => {
  const annotation = `# renovate: datasource=${datasource} depName=${depName}\n`;
  const line = text.split(annotation)[1]?.trimStart().split("\n")[0];
  assert.ok(line?.startsWith(`${name}: `), `${name} must have a Renovate annotation`);
  const version = line.slice(name.length + 2).replace(/^['"]|['"]$/g, "");
  assert.match(version, /^v?\d+\.\d+\.\d+$/, `${name} must be pinned to an exact version`);
  return version;
};
const npmVersion = pinnedVersion(ci, "NPM_VERSION", "npm", "npm");
assert.equal(pinnedVersion(release, "NPM_VERSION", "npm", "npm"), npmVersion, "CI and release must use the same npm CLI");
pinnedVersion(ci, "ACTIONLINT_VERSION", "github-releases", "rhysd/actionlint");
pinnedVersion(renovateWorkflow, "renovate-version", "docker", "ghcr.io/renovatebot/renovate");
for (const workflow of [ci, release]) {
  assert.match(workflow, /npm install --global "npm@\$NPM_VERSION" --ignore-scripts/);
  assert.match(workflow, /check-latest: true/);
}
assert.match(ci, /os: \[ubuntu-latest, macos-latest\]/);
assert.match(ci, /node: \['22', '24'\]/);
assert.match(ci.split("\n  workflow-validation:")[0], /fetch-depth: 0/, "release regression tests need the immutable initial source history");
assert.match(ci, /types: \[opened, synchronize, reopened\]/);
assert.match(ci, /name: CI passed/);
assert.match(ci, /needs: \[test, workflow-validation\]/);
assert.match(ci, /retention-days: 30/);
assert.match(ci, /gh release download "\$ACTIONLINT_VERSION" --repo rhysd\/actionlint/);
assert.match(ci, /sha256sum --check --ignore-missing/);
assert.doesNotMatch(ci.split("\n  workflow-validation:")[0], /npm audit/, "audits belong in the single tooling job");
assert.match(ci, /npm audit --audit-level=high/);
assert.match(ci, /npm audit --prefix \.github\/release-tools --audit-level=high/);
assert.deepEqual(pkg.overrides, { "@earendil-works/pi-coding-agent": { undici: "8.12.2" } }, "the temporary Pi development-tree Undici override must remain narrowly scoped");
assert.equal(pkg.devDependencies["@earendil-works/pi-coding-agent"], "1.4.0");
assert.equal(pkg.devDependencies["@earendil-works/pi-tui"], "1.4.0");
assert.deepEqual(pkg.peerDependencies, { "@earendil-works/pi-coding-agent": "*", "@earendil-works/pi-tui": "*" });
assert.match(release, /workflow_dispatch:/);
assert.match(release, /recovery_tag:/);
assert.match(release, /cancel-in-progress: false/);
assert.match(release, /PREPARED_INTEGRITY/);
assert.match(verifyJob, /GH_TOKEN: \$\{\{ github\.token \}\}/);
assert.match(verifyJob, /release-source\.mjs verify "\$TRUSTED_SHA"/);
assert.match(verifyJob, /node \.github\/release-tools\/release-source\.mjs verify "\$SHA"/);
assert.match(verifyJob, /npm run release:check/);
assert.match(verifyJob, /npm audit --audit-level=high/);
assert.match(verifyJob, /npm audit --prefix \.github\/release-tools --audit-level=high/);
assert.match(verifyJob, /release\.mjs prepare/);
assert.match(verifyJob, /actions\/upload-artifact@/);
assert.doesNotMatch(verifyJob, /contents: write|id-token: write|npm run (check|test|bench)/, "read-only preparation reuses PR CI and tests the actual prepared artifact");
assert.match(publishJob, /contents: write\s+id-token: write/);
assert.match(publishJob, /actions\/download-artifact@/);
assert.match(publishJob, /Confirm verified main is still current before publication/);
assert.match(publishJob, /publish-prepared\.mjs/);
assert.doesNotMatch(publishJob, /npm run (check|test)|npm ci --ignore-scripts/);
assert.doesNotMatch(release, /secrets\.|bootstrap|NPM_TOKEN|NODE_AUTH_TOKEN|semantic-release|release\.config\.mjs|release\.mjs run/, "release and recovery must remain OIDC-only with no token fallback");
assert.ok(!fs.existsSync(".github/release-tools/bootstrap-prepared.mjs"), "token bootstrap tooling must remain retired");
const adapters = read(".github/release-tools/adapters.mjs");
assert.doesNotMatch(adapters, /bootstrapToken|_authToken/, "publishing adapters must not accept npm credentials");
assert.match(adapters, /"--provenance"/);
assert.match(prTitle, /name: PR title passed/);
assert.match(prTitle, /edited/);
assert.match(prTitle, /timeout-minutes: 5/);
assert.match(prTitle, /Conventional Commit title/);
assert.ok(!fs.existsSync(".github/dependabot.yml"), "Renovate is the sole dependency update runner");
assert.deepEqual(renovate.enabledManagers.slice().sort(), ["custom.regex", "github-actions", "npm"]);
assert.ok(renovate.extends.includes("helpers:pinGitHubActionDigests"));
assert.equal(renovate.semanticCommits, "enabled");
assert.equal(renovate.semanticCommitType, "chore");
assert.equal(renovate.automerge, false);
assert.equal(renovate.vulnerabilityAlerts.enabled, true);
assert.equal(renovate.osvVulnerabilityAlerts, true);
assert.equal(renovate.customManagers.length, 1);
const manager = renovate.customManagers[0];
assert.equal(manager.customType, "regex");
assert.ok(manager.managerFilePatterns.includes("/^\\.github/workflows/.*\\.yml$/"));
const inlinePattern = new RegExp(manager.matchStrings[0], "g");
for (const [workflow, expected] of [[ci, ["npm", "rhysd/actionlint"]], [release, ["npm"]], [renovateWorkflow, ["ghcr.io/renovatebot/renovate"]]]) {
  assert.deepEqual([...workflow.matchAll(inlinePattern)].map((match) => match.groups.depName).sort(), expected.slice().sort(), "Renovate must discover every inline CI tool pin");
}
assert.match(renovateWorkflow, /schedule:/);
assert.match(renovateWorkflow, /workflow_dispatch:/);
assert.match(renovateWorkflow, /github\.repository == 'soulwaxx\/pi-skill-autocomplete'/);
assert.match(renovateWorkflow, /github\.ref == 'refs\/heads\/main'/);
assert.match(renovateWorkflow, /configurationFile: \.github\/renovate\.json/);
assert.match(renovateWorkflow, /token: \$\{\{ secrets\.RENOVATE_TOKEN \}\}/);
assert.match(renovateWorkflow, /RENOVATE_REPOSITORIES: \$\{\{ github\.repository \}\}/);
console.log(`Release configuration, OIDC-only split workflow permissions, and Renovate maintenance checked for ${pkg.name}@${pkg.version}`);
